package com.lrh.healthvivo.link

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.util.Properties

/**
 * Cross-implementation vectors for the watch link.
 *
 * `android/app/src/test/resources/link-vectors.properties` is generated by
 * `scripts/generate-link-vectors.mjs` from the **watch** implementation in
 * `watch/src/lib/link/`. Every assertion below therefore checks the Kotlin code against bytes the
 * JavaScript code actually produced, not against a second copy of the same idea. Regenerate the
 * file whenever the wire format changes:
 *
 *     node scripts/generate-link-vectors.mjs
 *
 * The watch suite (watch/test/link-wire.test.mjs, watch/test/link-server.test.mjs) checks the
 * other direction: it drives the watch protocol with an independent Node-crypto phone.
 */
class LinkVectorsTest {
    private val vectors: Properties = Properties().apply {
        // The file lives in src/test/resources. Depending on how the test runner assembles its
        // classpath it is reached either as a classpath resource or as a file relative to the
        // module directory, so accept both and report exactly what was tried.
        val candidates = listOf(
            LinkVectorsTest::class.java.classLoader?.getResourceAsStream("link-vectors.properties"),
            Thread.currentThread().contextClassLoader?.getResourceAsStream("link-vectors.properties"),
            java.io.File("src/test/resources/link-vectors.properties").takeIf { it.isFile }?.inputStream(),
            java.io.File("app/src/test/resources/link-vectors.properties").takeIf { it.isFile }?.inputStream()
        )
        val stream = candidates.firstOrNull { it != null }
            ?: error("link-vectors.properties is missing; run `node scripts/generate-link-vectors.mjs`")
        stream.use { load(it) }
    }

    private fun hex(key: String) = LinkBytes.fromHex(vectors.getProperty(key)!!)
    private fun text(key: String) = vectors.getProperty(key)!!
    private fun unsigned(key: String) = text(key).toLong()

    @Test fun generatedVectorsDescribeTheSameServiceAsTheKotlinConstants() {
        assertEquals(LinkFrames.SERVICE.toString(), text("service"))
        assertEquals(LinkFrames.CHARACTERISTIC.toString(), text("characteristic"))
        assertEquals(LinkFrames.PROTOCOL_VERSION, text("protocol").toInt())
        assertEquals(LinkFrames.ATT_PAYLOAD, text("sizes.attPayload").toInt())
        assertEquals(LinkFrames.DATA_PAYLOAD, text("sizes.dataPayload").toInt())
        assertEquals(LinkFrames.REPLY_PAYLOAD, text("sizes.replyPayload").toInt())
        assertEquals(LinkFrames.BEGIN_SIZE, text("sizes.begin").toInt())
        assertEquals(LinkFrames.END_SIZE, text("sizes.end").toInt())
        assertEquals(LinkFrames.MAX_BODY, text("sizes.maxBody").toInt())
        assertEquals(LinkFrames.MAX_REPLY, text("sizes.maxReply").toInt())
        // A DATA frame and a reply part must each fit one default-MTU ATT write.
        assertTrue(LinkFrames.DATA_HEADER + LinkFrames.DATA_PAYLOAD <= LinkFrames.ATT_PAYLOAD)
        assertTrue(LinkFrames.REPLY_HEADER + LinkFrames.REPLY_PAYLOAD <= LinkFrames.ATT_PAYLOAD)
        assertTrue(LinkFrames.MAX_POLL <= LinkFrames.REPLY_PAYLOAD)
    }

    @Test fun crc32MatchesTheWatchImplementation() {
        val count = text("crc32.count").toInt()
        assertTrue(count >= 4)
        for (index in 0 until count) {
            val input = LinkBytes.fromHex(text("crc32.$index.input"))
            val expected = unsigned("crc32.$index.expected")
            assertEquals("crc32 mismatch for vector $index", expected, LinkBytes.crc32(input).toLong() and 0xffffffffL)
        }
        assertEquals(0xcbf43926L, LinkBytes.crc32("123456789".toByteArray()).toLong() and 0xffffffffL)
    }

    @Test fun frameEncodersProduceTheExactWatchBytes() {
        val id = text("messageId").toInt()
        assertEquals(text("frames.begin"), LinkBytes.hex(LinkFrames.begin(id, LinkFrames.KIND_BODY, 1234, 0xdeadbeef.toInt())))
        assertEquals(text("frames.data"), LinkBytes.hex(LinkFrames.data(id, 22, byteArrayOf(1, 2, 3, 4, 5))))
        assertEquals(text("frames.end"), LinkBytes.hex(LinkFrames.end(id, 0x01020304)))
        assertEquals(text("frames.poll"), LinkBytes.hex(LinkFrames.poll(id, 11, LinkFrames.MAX_POLL)))
        assertEquals(text("frames.release"), LinkBytes.hex(LinkFrames.release(id)))
        assertEquals(text("frames.reset"), LinkBytes.hex(LinkFrames.reset()))
        assertTrue(LinkFrames.begin(id, LinkFrames.KIND_BODY, 1234, 0).size <= LinkFrames.ATT_PAYLOAD)
    }

    @Test fun theGreetingParsesTheWatchBytes() {
        val greeting = LinkProtocol.greeting(hex("frames.greeting"))
        assertEquals(unsigned("epoch"), greeting.epoch)
        assertTrue(greeting.enrolled)
        assertEquals(3, greeting.reads)
        assertEquals(4, greeting.writes)
        assertEquals(1, greeting.surface)
        assertTrue(greeting.requestPending)
        assertFalse(greeting.paused)
        assertTrue(LinkProtocol.isGreeting(hex("frames.greeting")))
        assertFalse(LinkProtocol.isReceipt(hex("frames.greeting")))
    }

    @Test fun sessionKeysMatchTheWatchDerivation() {
        val session = LinkSession(text("secret"), unsigned("epoch"), hex("nonce"))
        assertArrayEquals(hex("session.hello"), session.hello)
        // The enrollment payload starts with the raw 32 credential bytes.
        val enrollment = session.enrollment
        assertEquals(LinkFrames.ENROLL_SIZE, enrollment.size)
        assertArrayEquals(java.util.Base64.getDecoder().decode(text("secret")), enrollment.copyOf(32))
        assertArrayEquals(hex("session.hello"), enrollment.copyOfRange(32, enrollment.size))
    }

    @Test fun anEncryptedBodyMatchesTheWatchBytesByteForByte() {
        val session = LinkSession(text("secret"), unsigned("epoch"), hex("nonce"))
        val body = session.encrypt(text("message"), text("messageId").toInt(), hex("iv"))
        assertEquals(text("body"), LinkBytes.hex(body))
    }

    @Test fun aWatchReplyVerifiesAndDecrypts() {
        val session = LinkSession(text("secret"), unsigned("epoch"), hex("nonce"))
        val reply = hex("frames.reply")
        assertEquals(text("replyText"), session.decrypt(reply, text("messageId").toInt()))
    }

    @Test fun aTamperedReplyIsRejectedBeforeItIsDecrypted() {
        val session = LinkSession(text("secret"), unsigned("epoch"), hex("nonce"))
        val tampered = hex("frames.reply").also { it[it.size - 1] = (it[it.size - 1].toInt() xor 1).toByte() }
        try { session.decrypt(tampered, text("messageId").toInt()); fail("a tampered reply was accepted") }
        catch (expected: IllegalArgumentException) { assertTrue(expected.message!!.contains("校验失败")) }
        // A reply replayed under a different transfer id must also fail.
        try { session.decrypt(hex("frames.reply"), text("messageId").toInt() + 1); fail("a reply under the wrong id was accepted") }
        catch (expected: IllegalArgumentException) { }
    }

    @Test fun aReceiptFromTheWatchIsAuthenticated() {
        val session = LinkSession(text("secret"), unsigned("epoch"), hex("nonce"))
        val receipt = session.receipt(hex("frames.receipt"))
        assertEquals(LinkFrames.STATE_SAVED, receipt.state)
        assertEquals(text("messageId").toInt(), receipt.id)
        assertEquals(100, receipt.value)
        assertFalse(receipt.requested)
    }

    @Test fun aReceiptWithAnotherSecretIsRejected() {
        val other = LinkSession(java.util.Base64.getEncoder().encodeToString(ByteArray(32) { 7 }), unsigned("epoch"), hex("nonce"))
        try { other.receipt(hex("frames.receipt")); fail("a receipt signed with another secret was accepted") }
        catch (expected: IllegalArgumentException) { assertTrue(expected.message!!.contains("会话已失效")) }
    }

    @Test fun aReplyPartCarriesItsTransferIdAndOffset() {
        val id = text("messageId").toInt()
        val payload = LinkBytes.fromHex("000102030405060708090a")
        // link-vectors.properties pins the reply, so build the part from the Kotlin encoder and
        // check the reader accepts exactly that shape and refuses every deviation.
        val part = LinkBytes.concat(byteArrayOf(LinkFrames.REPLY_MARK.toByte()), LinkBytes.u32(id), LinkBytes.u32(11), payload)
        assertArrayEquals(payload, LinkProtocol.replyChunk(part, id, 11, 64))
        assertEquals(LinkFrames.ATT_PAYLOAD, part.size)
        assertTrue(LinkProtocol.isReplyPart(part))
        listOf(
            LinkBytes.concat(byteArrayOf(0), LinkBytes.u32(id), LinkBytes.u32(11), payload),
            LinkBytes.concat(byteArrayOf(LinkFrames.REPLY_MARK.toByte()), LinkBytes.u32(id + 1), LinkBytes.u32(11), payload),
            LinkBytes.concat(byteArrayOf(LinkFrames.REPLY_MARK.toByte()), LinkBytes.u32(id), LinkBytes.u32(12), payload),
            byteArrayOf(LinkFrames.REPLY_MARK.toByte())
        ).forEach { broken ->
            try { LinkProtocol.replyChunk(broken, id, 11, 64); fail("a malformed reply part was accepted") }
            catch (expected: IllegalArgumentException) { }
        }
        // A chunk that would run past the announced length is refused too.
        try { LinkProtocol.replyChunk(part, id, 11, 20); fail("an overlong reply part was accepted") }
        catch (expected: IllegalArgumentException) { }
    }

    @Test fun aFailedHandshakeIsReportedAsAShortMarkerNotAReceipt() {
        val failure = byteArrayOf(LinkFrames.FAILURE_MARK.toByte(), 2)
        assertTrue(LinkProtocol.isFailure(failure))
        assertEquals(2, LinkProtocol.failure(failure).stage)
        assertFalse(LinkProtocol.isFailure(byteArrayOf(LinkFrames.FAILURE_MARK.toByte())))
        assertFalse(LinkProtocol.isGreeting(failure))
        assertFalse(LinkProtocol.isReceipt(failure))
    }

    @Test fun theGreetingRejectsAnotherProtocolVersionAndAnEmptyEpoch() {
        val greeting = hex("frames.greeting")
        val otherVersion = greeting.copyOf().also { it[1] = 2 }
        try { LinkProtocol.greeting(otherVersion); fail("another protocol version was accepted") }
        catch (expected: IllegalArgumentException) { assertTrue(expected.message!!.contains("0.7.1")) }
        val zeroEpoch = greeting.copyOf().also { for (index in 3 until 11) it[index] = 0 }
        try { LinkProtocol.greeting(zeroEpoch); fail("a zero epoch was accepted") }
        catch (expected: IllegalArgumentException) { }
        try { LinkProtocol.greeting(ByteArray(19)); fail("a short greeting was accepted") }
        catch (expected: IllegalArgumentException) { }
    }

    @Test fun chunksSplitsABodyIntoAttSizedFramesThatReassemble() {
        val body = ByteArray(37) { (it * 7 and 0xff).toByte() }
        val frames = LinkFrames.chunks(9, body)
        assertEquals((37 + LinkFrames.DATA_PAYLOAD - 1) / LinkFrames.DATA_PAYLOAD, frames.size)
        assertTrue(frames.all { it.size <= LinkFrames.ATT_PAYLOAD })
        val rebuilt = ByteArray(body.size)
        var offset = 0
        frames.forEach { frame ->
            val decoded = LinkFrames.decode(frame)
            assertEquals(LinkFrames.OP_DATA, decoded.op)
            assertEquals(9, decoded.id)
            assertEquals(offset, decoded.offset)
            decoded.chunk.copyInto(rebuilt, offset)
            offset += decoded.chunk.size
        }
        assertArrayEquals(body, rebuilt)
    }

    @Test fun decodeRejectsMalformedFramesWithoutThrowing() {
        val cases = listOf(
            ByteArray(0) to "empty",
            byteArrayOf(LinkFrames.OP_DATA.toByte()) to "short",
            LinkBytes.concat(byteArrayOf(LinkFrames.OP_DATA.toByte()), LinkBytes.u32(0), LinkBytes.u32(0), byteArrayOf(1)) to "id",
            LinkFrames.begin(1, LinkFrames.KIND_BODY, 1, 1).copyOf(13) to "begin-length",
            LinkBytes.concat(byteArrayOf(LinkFrames.OP_DATA.toByte()), LinkBytes.u32(1), LinkBytes.u32(0)) to "data-length",
            LinkBytes.concat(byteArrayOf(LinkFrames.OP_END.toByte()), LinkBytes.u32(1)) to "end-length",
            LinkBytes.concat(byteArrayOf(LinkFrames.OP_POLL.toByte()), LinkBytes.u32(1), LinkBytes.u32(0), byteArrayOf(15, 15)) to "poll-length",
            LinkFrames.release(1).copyOf(4) to "short",
            LinkBytes.concat(byteArrayOf(9), LinkBytes.u32(1)) to "op",
            byteArrayOf(LinkFrames.OP_RESET.toByte(), 0) to "reset-length"
        )
        for ((frame, error) in cases) assertEquals("expected $error", error, LinkFrames.decode(frame).error)
    }
}
